// Package fill_event defines the wire payload for a committed fill notification.
package fill_event

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	// Version identifies the supported fill notification contract.
	Version = "1.0"
	// DefaultTopic carries committed fill events using this contract.
	DefaultTopic = "tradingbot.trade.filled.v1"
	// SourceExchangeFixture identifies a fill generated by the simulated exchange.
	SourceExchangeFixture = "exchange_fixture"
	maxSize               = 4 * 1024
)

var (
	errInvalidJSON   = errors.New("invalid trade event JSON")
	idPattern        = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:/@-]{0,127}$`)
	decimalPattern   = regexp.MustCompile(`^(0|[1-9][0-9]{0,37})(\.[0-9]{1,18})?$`)
	currencyPattern  = regexp.MustCompile(`^[A-Z][A-Z0-9]{1,11}$`)
	timestampPattern = regexp.MustCompile(`^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$`)
)

// Event reports one fill. The producer assigns a stable ID unique across
// accounts and modes. Each separately recorded partial fill has its own ID.
type Event struct {
	Version      string    `json:"version"`
	ID           string    `json:"id"`
	Mode         string    `json:"mode"`
	Source       string    `json:"source,omitempty"`
	AccountID    string    `json:"account_id"`
	InstrumentID string    `json:"instrument_id"`
	Side         string    `json:"side"`
	Quantity     string    `json:"quantity"`
	Price        string    `json:"price"`
	Currency     string    `json:"currency"`
	FilledAt     time.Time `json:"filled_at"`
}

// Decode accepts one bounded JSON object and validates all wire fields.
func Decode(data []byte) (Event, error) {
	if len(data) > maxSize {
		return Event{}, errors.New("trade event exceeds the wire size limit")
	}
	fields, err := decodeFields(data)
	if err != nil {
		return Event{}, errInvalidJSON
	}
	if source, present := fields["source"]; present && source != SourceExchangeFixture {
		return Event{}, errors.New("invalid trade fill source")
	}
	timestamp := fields["filled_at"]
	if !timestampPattern.MatchString(timestamp) {
		return Event{}, errors.New("invalid trade fill timestamp")
	}
	filledAt, err := time.Parse(time.RFC3339Nano, timestamp)
	if err != nil {
		return Event{}, errors.New("invalid trade fill timestamp")
	}
	event := Event{
		Version:      fields["version"],
		ID:           fields["id"],
		Mode:         fields["mode"],
		Source:       fields["source"],
		AccountID:    fields["account_id"],
		InstrumentID: fields["instrument_id"],
		Side:         fields["side"],
		Quantity:     fields["quantity"],
		Price:        fields["price"],
		Currency:     fields["currency"],
		FilledAt:     filledAt,
	}
	if err := event.Validate(); err != nil {
		return Event{}, err
	}
	return event, nil
}

func decodeFields(data []byte) (map[string]string, error) {
	if !utf8.Valid(data) {
		return nil, errInvalidJSON
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if token, err := decoder.Token(); err != nil || token != json.Delim('{') {
		return nil, errInvalidJSON
	}
	fields := make(map[string]string, 11)
	for decoder.More() {
		keyToken, err := decoder.Token()
		key, isString := keyToken.(string)
		if err != nil || !isString {
			return nil, errInvalidJSON
		}
		switch key {
		case "version", "id", "mode", "source", "account_id", "instrument_id", "side", "quantity", "price", "currency", "filled_at":
		default:
			return nil, errInvalidJSON
		}
		if _, duplicate := fields[key]; duplicate {
			return nil, errInvalidJSON
		}
		valueToken, err := decoder.Token()
		value, isString := valueToken.(string)
		if err != nil || !isString {
			return nil, errInvalidJSON
		}
		fields[key] = value
	}
	if token, err := decoder.Token(); err != nil || token != json.Delim('}') {
		return nil, errInvalidJSON
	}
	if _, err := decoder.Token(); err != io.EOF {
		return nil, errInvalidJSON
	}
	return fields, nil
}

// Validate checks an event before the producer serializes it.
func (e Event) Validate() error {
	switch {
	case e.Version != Version:
		return errors.New("unsupported trade event version")
	case e.Mode != "paper" && e.Mode != "live":
		return errors.New("invalid trade fill mode")
	case e.Source != "" && (e.Source != SourceExchangeFixture || e.Mode != "paper"):
		return errors.New("invalid trade fill source or mode")
	case !idPattern.MatchString(e.ID), !idPattern.MatchString(e.AccountID), !idPattern.MatchString(e.InstrumentID):
		return errors.New("invalid trade fill identifiers")
	case e.Side != "BUY" && e.Side != "SELL":
		return errors.New("invalid trade fill side")
	case !isPositiveDecimal(e.Quantity), !isPositiveDecimal(e.Price):
		return errors.New("trade fill quantity and price must be positive decimal strings")
	case !currencyPattern.MatchString(e.Currency):
		return errors.New("invalid trade fill currency")
	}
	_, offset := e.FilledAt.Zone()
	if offset != 0 || e.FilledAt.Year() < 1000 || e.FilledAt.Year() > 9999 {
		return errors.New("invalid trade fill timestamp")
	}
	return nil
}

func isPositiveDecimal(value string) bool {
	return decimalPattern.MatchString(value) && strings.ContainsAny(value, "123456789")
}
